import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem68 exige identidade e preserva operação sem prometer desempenho',()=>{for(const [id,titulo] of [['CvM3xyDY4t5BF7XdPjF6','Canivete Militar Tático Defesa Bolso Aço Inox Caça Ec-713'],['d6VCoNciFGrUwOkaNoDU','Natura Ilía Completa 50ml Feminino Parfum Spray']]){const p={id,titulo,preco:'preservado',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.equal(x.preco,p.preco);assert.equal(x.linkAfiliado,p.linkAfiliado);assert.deepEqual(correctProductData(x),x);assert.equal(correctProductData({...p,titulo:'Outro produto',comentario:'manter'}).comentario,'manter');assert.doesNotMatch(x.pros,/defesa|militar|tático|duradouro|sofisticad/i);}});
